insert or ignore into albums (id, slug, title, artist, description, price, genre, image_urls, cover_url, catalog_number, release_year, in_stock) values
  (1, 'bbq', 'Ash & Smoke', 'Rusty Char-Broil', 'The perfect gift for the BBQ enthusiast in your life!', 16.99, 'cookbook', '["/images/bbq-1.png","/images/bbq-2.png","/images/bbq-3.png"]', '/images/bbq-1.png', '978-0525559474', 2020, 1),
  (2, 'heavy-metal', 'Heavy Metal Guitar Riffs', 'Axe Master Krush', 'The ultimate guide to heavy metal guitar riffs!', 27.0, 'art', '["/images/heavy-metal-1.png","/images/heavy-metal-2.png","/images/heavy-metal-3.png"]', '/images/heavy-metal-1.png', '978-0735211292', 2018, 1),
  (3, 'three-ways', 'Three Ways to Change Your Life', 'Wisdom Sage', 'Life-changing guidance for modern living and personal growth.', 28.99, 'self-help', '["/images/three-ways-1.png","/images/three-ways-2.png","/images/three-ways-3.png"]', '/images/three-ways-1.png', '978-0061120084', 2021, 0),
  (4, 'midnight-platform', 'The Midnight Platform', 'Nora Vale', 'When the last train arrives with an empty carriage and a suitcase full of letters, a retired stationmaster has one night to unravel a disappearance that began thirty years ago. An atmospheric railway mystery for rainy evenings.', 24.99, 'mystery', '["/images/midnight-platform-1.png","/images/midnight-platform-2.png","/images/midnight-platform-3.png"]', '/images/midnight-platform-1.png', '978-1-55555-010-3', 2025, 1),
  (5, 'wild-windowsill', 'Wild at the Windowsill', 'Fern Holloway', 'Turn even the smallest apartment into a leafy retreat. Grow kitchen herbs, coax cuttings into roots, and build a thriving windowsill garden with illustrated projects and practical advice for every season.', 22.5, 'gardening', '["/images/wild-windowsill-1.png","/images/wild-windowsill-2.png","/images/wild-windowsill-3.png"]', '/images/wild-windowsill-1.png', '978-1-55555-011-0', 2024, 1),
  (6, 'saltwater-summer', 'Saltwater Summer', 'June Marlowe', 'Three old friends inherit a weather-beaten beach cottage and a summer to decide what comes next. A warm, witty coastal novel about second chances, found family, and the things the tide brings back.', 19.99, 'fiction', '["/images/saltwater-summer-1.png","/images/saltwater-summer-2.png","/images/saltwater-summer-3.png"]', '/images/saltwater-summer-1.png', '978-1-55555-012-7', 2026, 1),
  (7, 'briarwood-lanterns', 'Lanterns of Briarwood', 'Elara Finch', 'An apprentice lantern keeper discovers that the lights guiding travelers through Briarwood are fading. With a stubborn fox and a borrowed spellbook, she sets out to mend the forest before its forgotten paths disappear.', 25.99, 'fantasy', '["/images/briarwood-lanterns-1.png","/images/briarwood-lanterns-2.png","/images/briarwood-lanterns-3.png"]', '/images/briarwood-lanterns-1.png', '9781555550134', 2026, 1),
  (8, 'orbit-of-glass', 'Orbit of Glass', 'Dorian Keene', 'A repair pilot aboard a glass-ringed orbital city intercepts a message from a planet everyone believes is empty. Following its coordinates means choosing between the home he built and the people who were left behind.', 26.5, 'fantasy', '["/images/orbit-of-glass-1.png","/images/orbit-of-glass-2.png","/images/orbit-of-glass-3.png"]', '/images/orbit-of-glass-1.png', '9781555550141', 2025, 1),
  (9, 'apricot-house', 'The Apricot House', 'Clara Wren', 'Restoring her grandmother''s apricot-colored house was supposed to be a fresh start, without complications. Then the carpenter next door arrives with a rescued dog, a talent for terrible jokes, and plans that fit a little too well with hers.', 18.99, 'fiction', '["/images/apricot-house-1.png","/images/apricot-house-2.png","/images/apricot-house-3.png"]', '/images/apricot-house-1.png', '9781555550158', 2026, 1),
  (10, 'small-roads', 'A Map of Small Roads', 'Ellis Rowan', 'Leave the highway behind for quiet villages, roadside bakeries, overlooked trails, and the pleasures of getting a little lost. Fourteen unhurried journeys pair thoughtful travel essays with hand-drawn maps and practical stops along the way.', 29.99, 'travel', '["/images/small-roads-1.png","/images/small-roads-2.png","/images/small-roads-3.png"]', '/images/small-roads-1.png', '9781555550165', 2024, 1),
  (11, 'bread-before-dawn', 'Bread Before Dawn', 'Ada Mercer', 'Make your kitchen smell like a neighborhood bakery. From forgiving first loaves to slow-fermented sourdough and buttery breakfast buns, these recipes explain the small decisions that turn flour, water, and time into something worth sharing.', 32.0, 'cookbook', '["/images/bread-before-dawn-1.png","/images/bread-before-dawn-2.png","/images/bread-before-dawn-3.png"]', '/images/bread-before-dawn-1.png', '9781555550172', 2025, 1),
  (12, 'quiet-observatory', 'The Quiet Observatory', 'Mira Solis', 'Discover the night sky from a backyard, a balcony, or a favorite dark hillside. Clear explanations and beautifully drawn charts introduce the Moon, the planets, and the patient art of noticing what changes overhead.', 27.99, 'nonfiction', '["/images/quiet-observatory-1.png","/images/quiet-observatory-2.png","/images/quiet-observatory-3.png"]', '/images/quiet-observatory-1.png', '9781555550189', 2026, 1),
  (13, 'ink-and-tide', 'Ink & Tide', 'Willa Hart', 'Poems about harbor mornings, long-distance love, unanswered letters, and learning to begin again. These spare, intimate pieces find a steady rhythm in the restless meeting of water and shore.', 17.5, 'fiction', '["/images/ink-and-tide-1.png","/images/ink-and-tide-2.png","/images/ink-and-tide-3.png"]', '/images/ink-and-tide-1.png', '9781555550196', 2024, 1),
  (14, 'clay-in-your-hands', 'Clay in Your Hands', 'Theo Alder', 'Start with a lump of clay and make objects you will love using every day. Friendly lessons in hand-building, wheel work, glazing, and finishing lead from your first pinch pot to mugs, bowls, and small sculptural pieces.', 30.0, 'art', '["/images/clay-in-your-hands-1.png","/images/clay-in-your-hands-2.png","/images/clay-in-your-hands-3.png"]', '/images/clay-in-your-hands-1.png', '9781555550202', 2025, 1),
  (15, 'last-orchard', 'The Last Orchard', 'Maeve Linden', 'When her father can no longer tend the family orchard, a radio producer returns to a town she thought she had outgrown. One harvest season brings old arguments, unexpected friendships, and a chance to choose what deserves to be kept.', 23.99, 'fiction', '["/images/last-orchard-1.png","/images/last-orchard-2.png","/images/last-orchard-3.png"]', '/images/last-orchard-1.png', '9781555550219', 2026, 1),
  (16, 'vinyl-after-hours', 'Vinyl After Hours', 'Leon Avery', 'Follow the grooves through late-night record shops, listening rooms, and the stories behind unforgettable albums. A personal guide to careful listening, collecting with curiosity, and building a soundtrack that feels like your own.', 28.99, 'art', '["/images/vinyl-after-hours-1.png","/images/vinyl-after-hours-2.png","/images/vinyl-after-hours-3.png"]', '/images/vinyl-after-hours-1.png', '9781555550226', 2023, 1),
  (17, 'clockmakers-letter', 'The Clockmaker''s Letter', 'Iris Bell', 'A letter hidden inside a broken mantel clock sends a museum conservator searching for its missing maker. Every repaired mechanism reveals another clue, but someone is determined to keep the final hour from striking.', 24.5, 'mystery', '["/images/clockmakers-letter-1.png","/images/clockmakers-letter-2.png","/images/clockmakers-letter-3.png"]', '/images/clockmakers-letter-1.png', '9781555550233', 2025, 1),
  (18, 'woodland-field-notes', 'Woodland Field Notes', 'Rowan Moss', 'Slow down on your next woodland walk. Learn to recognize familiar trees, spot signs of animal life, follow seasonal changes, and record small discoveries with sketches, simple observations, and a little wonder.', 21.99, 'gardening', '["/images/woodland-field-notes-1.png","/images/woodland-field-notes-2.png","/images/woodland-field-notes-3.png"]', '/images/woodland-field-notes-1.png', '9781555550240', 2024, 1),
  (19, 'color-outside-city', 'Color Outside the City', 'Nina Flores', 'Bring a sketchbook to markets, side streets, rooftops, and train platforms. An approachable guide to urban sketching combines watercolor lessons, playful drawing exercises, and the confidence to capture a place before the moment passes.', 34.0, 'art', '["/images/color-outside-city-1.png","/images/color-outside-city-2.png","/images/color-outside-city-3.png"]', '/images/color-outside-city-1.png', '9781555550257', 2026, 1),
  (20, 'slower-sunday', 'A Slower Kind of Sunday', 'Lena Birch', 'Create breathing room in a busy week with small rituals that make ordinary days feel more spacious. Gentle prompts for rest, attention, and time with others help you build a life you can enjoy at its own pace.', 20.99, 'self-help', '["/images/slower-sunday-1.png","/images/slower-sunday-2.png","/images/slower-sunday-3.png"]', '/images/slower-sunday-1.png', '9781555550264', 2025, 1),
  (21, 'ninth-passenger', 'The Ninth Passenger', 'Margot Hale', 'Eight passengers board a mountain tram, but nine shadows appear in the station photograph. A missing-persons detective must untangle their stories before the next stop vanishes into the snow.', 24.99, 'mystery', '["/images/ninth-passenger-1.png","/images/ninth-passenger-2.png","/images/ninth-passenger-3.png"]', '/images/ninth-passenger-1.png', '9781555550271', 2026, 1),
  (22, 'europa-wakes', 'When Europa Wakes', 'Soren Voss', 'Beneath the ice of Europa, an oceanographer hears a pattern that sounds like a reply. With the research station losing power, her crew must decide whether first contact is worth the journey home.', 27.5, 'fantasy', '["/images/europa-wakes-1.png","/images/europa-wakes-2.png","/images/europa-wakes-3.png"]', '/images/europa-wakes-1.png', '9781555550288', 2025, 1),
  (23, 'atlas-lost-doors', 'Atlas of Lost Doors', 'Tamsin Reed', 'A locksmith inherits an atlas whose maps change each night. Every door it reveals opens onto a forgotten kingdom, and the one she most needs to find has been erased by someone who knows her name.', 26.99, 'fantasy', '["/images/atlas-lost-doors-1.png","/images/atlas-lost-doors-2.png","/images/atlas-lost-doors-3.png"]', '/images/atlas-lost-doors-1.png', '9781555550295', 2026, 1),
  (24, 'signal-blackwater', 'Signal at Blackwater', 'Jonah Cross', 'A coastal radio operator receives a distress call from a ship that sank a decade ago. As the storm closes the harbor, each transmission points to someone still living in the town.', 23.99, 'mystery', '["/images/signal-blackwater-1.png","/images/signal-blackwater-2.png","/images/signal-blackwater-3.png"]', '/images/signal-blackwater-1.png', '9781555550301', 2025, 1),
  (25, 'postcards-lisbon', 'Postcards from Lisbon', 'Sofia Lane', 'A postcard meant for someone else leads a translator through Lisbon one cafe at a time. The sender has left a trail of small invitations, and a chance to fall in love with a city and a stranger.', 19.5, 'fiction', '["/images/postcards-lisbon-1.png","/images/postcards-lisbon-2.png","/images/postcards-lisbon-3.png"]', '/images/postcards-lisbon-1.png', '9781555550318', 2026, 1),
  (26, 'secondhand-piano', 'The Secondhand Piano', 'Celia North', 'An old upright piano arrives at a community center with a notebook tucked behind its keys. The songs inside bring together a night-shift nurse, a shy teenager, and a retired teacher who thought her music days were over.', 22.99, 'fiction', '["/images/secondhand-piano-1.png","/images/secondhand-piano-2.png","/images/secondhand-piano-3.png"]', '/images/secondhand-piano-1.png', '9781555550325', 2024, 1),
  (27, 'seamstress-bell-street', 'The Seamstress of Bell Street', 'Agnes Hartwell', 'In a changing industrial town, a seamstress stitches secret messages into the hems of her clients'' dresses. One commission draws her into a fight for fair wages and a friendship that changes the course of her life.', 25.5, 'fiction', '["/images/seamstress-bell-street-1.png","/images/seamstress-bell-street-2.png","/images/seamstress-bell-street-3.png"]', '/images/seamstress-bell-street-1.png', '9781555550332', 2025, 1),
  (28, 'life-above-clouds', 'Life Above the Clouds', 'Mara Ellison', 'The fictional life of trailblazing balloonist Evelyn March unfolds through journals, workshop sketches, and the people who kept her grounded. A story of stubborn curiosity, hard-earned confidence, and skies that never stopped calling.', 28.99, 'nonfiction', '["/images/life-above-clouds-1.png","/images/life-above-clouds-2.png","/images/life-above-clouds-3.png"]', '/images/life-above-clouds-1.png', '9781555550349', 2026, 1),
  (29, 'city-beneath-feet', 'The City Beneath Our Feet', 'Felix Ward', 'Follow the forgotten rivers, sealed stations, foundations, and tunnels hidden beneath an imagined city. Richly illustrated chapters show how ordinary streets preserve layers of engineering, ambition, and everyday life.', 29.5, 'nonfiction', '["/images/city-beneath-feet-1.png","/images/city-beneath-feet-2.png","/images/city-beneath-feet-3.png"]', '/images/city-beneath-feet-1.png', '9781555550356', 2025, 1),
  (30, 'pocketful-weather', 'A Pocketful of Weather', 'Kit Calder', 'Read clouds, notice shifting winds, and discover why the sky changes its mind. Friendly explanations, observation projects, and illustrated weather journals make atmospheric science part of an ordinary day outside.', 21.99, 'nonfiction', '["/images/pocketful-weather-1.png","/images/pocketful-weather-2.png","/images/pocketful-weather-3.png"]', '/images/pocketful-weather-1.png', '9781555550363', 2026, 1),
  (31, 'birds-between-buildings', 'Birds Between Buildings', 'Avery Finch', 'Find surprising wildlife on rooftops, sidewalks, and the trees outside your door. This illustrated guide introduces familiar urban birds and simple ways to observe their calls, habits, and seasonal journeys.', 24.5, 'gardening', '["/images/birds-between-buildings-1.png","/images/birds-between-buildings-2.png","/images/birds-between-buildings-3.png"]', '/images/birds-between-buildings-1.png', '9781555550370', 2024, 1),
  (32, 'night-garden', 'The Night Garden', 'Sylvie Bloom', 'Plant a garden that comes alive after sunset. Explore pale blossoms, fragrant herbs, reflective leaves, and thoughtful lighting through practical planting plans for patios, balconies, and small backyards.', 27.99, 'gardening', '["/images/night-garden-1.png","/images/night-garden-2.png","/images/night-garden-3.png"]', '/images/night-garden-1.png', '9781555550387', 2025, 1),
  (33, 'sunday-noodle-shop', 'Sunday at the Noodle Shop', 'Emi Tanaka', 'Bring the comfort of a neighborhood noodle shop to your kitchen. Broths, hand-folded dumplings, crisp toppings, and weeknight bowls come with clear techniques and stories about gathering around a shared table.', 33.0, 'cookbook', '["/images/sunday-noodle-shop-1.png","/images/sunday-noodle-shop-2.png","/images/sunday-noodle-shop-3.png"]', '/images/sunday-noodle-shop-1.png', '9781555550394', 2026, 1),
  (34, 'citrus-and-salt', 'Citrus & Salt', 'Luca Marin', 'Cook bright, generous meals with lemons, oranges, herbs, and a well-stocked pantry. From simple salads to slow-roasted suppers, these recipes celebrate bold flavors and the pleasure of feeding friends.', 31.99, 'cookbook', '["/images/citrus-and-salt-1.png","/images/citrus-and-salt-2.png","/images/citrus-and-salt-3.png"]', '/images/citrus-and-salt-1.png', '9781555550400', 2025, 1),
  (35, 'study-in-blue', 'A Study in Blue', 'Inez Porter', 'Explore the many moods of one color through paint, collage, ink, and observation. Guided studio exercises and richly illustrated essays invite beginners and practiced artists to build their own visual language.', 35.0, 'art', '["/images/study-in-blue-1.png","/images/study-in-blue-2.png","/images/study-in-blue-3.png"]', '/images/study-in-blue-1.png', '9781555550417', 2026, 1),
  (36, 'light-through-lens', 'Light Through the Lens', 'Callum Stone', 'Learn to see light before reaching for your camera. Practical lessons in shadows, reflections, framing, and timing pair with quiet photo essays and assignments that work anywhere you can take a walk.', 34.99, 'art', '["/images/light-through-lens-1.png","/images/light-through-lens-2.png","/images/light-through-lens-3.png"]', '/images/light-through-lens-1.png', '9781555550424', 2025, 1),
  (37, 'stitch-by-stitch', 'Stitch by Stitch', 'Nell Weaver', 'Make useful, beautiful things with a needle, thread, and a little patience. Illustrated lessons guide you through embroidery, visible mending, and simple fabric projects that turn small scraps into lasting favorites.', 26.5, 'art', '["/images/stitch-by-stitch-1.png","/images/stitch-by-stitch-2.png","/images/stitch-by-stitch-3.png"]', '/images/stitch-by-stitch-1.png', '9781555550431', 2024, 1),
  (38, 'carving-everyday', 'Carving the Everyday', 'Owen Birch', 'Shape spoons, small bowls, hooks, and keepsakes from ordinary pieces of wood. Thoughtful step-by-step projects explain grain, tool care, and finishing while making room for the marks of your own hands.', 29.99, 'art', '["/images/carving-everyday-1.png","/images/carving-everyday-2.png","/images/carving-everyday-3.png"]', '/images/carving-everyday-1.png', '9781555550448', 2025, 1),
  (39, 'shape-of-jazz', 'The Shape of Jazz', 'Miles Bellamy', 'Listen for the conversation inside a great jazz performance. Accessible essays on rhythm, improvisation, and small-group playing follow musicians from practice rooms to late-night stages, with listening prompts for curious ears.', 28.5, 'art', '["/images/shape-of-jazz-1.png","/images/shape-of-jazz-2.png","/images/shape-of-jazz-3.png"]', '/images/shape-of-jazz-1.png', '9781555550455', 2026, 1),
  (40, 'north-by-ferry', 'North by Ferry', 'Freya Holm', 'Travel slowly through island harbors, misty crossings, and towns best reached by water. Evocative essays, illustrated routes, and practical notes make a case for letting the journey set the pace.', 30.0, 'travel', '["/images/north-by-ferry-1.png","/images/north-by-ferry-2.png","/images/north-by-ferry-3.png"]', '/images/north-by-ferry-1.png', '9781555550462', 2025, 1),
  (41, 'two-wheels-no-hurry', 'Two Wheels, No Hurry', 'Jamie Brooks', 'Trade deadlines for quiet lanes, roadside picnics, and the occasional wrong turn. This illustrated collection of cycling journeys pairs personal stories with packing advice, route planning, and encouragement to start close to home.', 24.99, 'travel', '["/images/two-wheels-no-hurry-1.png","/images/two-wheels-no-hurry-2.png","/images/two-wheels-no-hurry-3.png"]', '/images/two-wheels-no-hurry-1.png', '9781555550479', 2024, 1),
  (42, 'spaces-between-rain', 'The Spaces Between Rain', 'Eden Rivers', 'A collection of poems about kitchen windows, city walks, old friendships, and the pause after a storm. Delicate images and plainspoken lines find moments of shelter in a world that keeps moving.', 18.99, 'fiction', '["/images/spaces-between-rain-1.png","/images/spaces-between-rain-2.png","/images/spaces-between-rain-3.png"]', '/images/spaces-between-rain-1.png', '9781555550486', 2026, 1),
  (43, 'begin-ten-minutes', 'Begin with Ten Minutes', 'Aria Wells', 'Make space for the things you keep postponing with small, repeatable starts. Gentle exercises for attention, creativity, movement, and rest help you turn ten spare minutes into a habit you actually enjoy.', 20.5, 'self-help', '["/images/begin-ten-minutes-1.png","/images/begin-ten-minutes-2.png","/images/begin-ten-minutes-3.png"]', '/images/begin-ten-minutes-1.png', '9781555550493', 2025, 1),
  (44, 'questions-long-walk', 'Questions for a Long Walk', 'Hugo Vale', 'Take everyday questions about choice, friendship, time, and meaning out for a walk. Brief essays introduce philosophical ideas through ordinary encounters, leaving room for your own answers to develop along the path.', 22.5, 'self-help', '["/images/questions-long-walk-1.png","/images/questions-long-walk-2.png","/images/questions-long-walk-3.png"]', '/images/questions-long-walk-1.png', '9781555550509', 2024, 1),
  (45, 'pip-paper-moon', 'Pip and the Paper Moon', 'Mabel Quinn', 'When a little mouse folds a moon from paper, the whole neighborhood wants to help it shine. A warmly illustrated story about making things together, trying again, and finding magic in the simplest materials.', 17.99, 'children', '["/images/pip-paper-moon-1.png","/images/pip-paper-moon-2.png","/images/pip-paper-moon-3.png"]', '/images/pip-paper-moon-1.png', '9781555550516', 2026, 1),
  (46, 'fox-found-tuesday', 'The Fox Who Found Tuesday', 'Otis Fern', 'A forgetful fox wakes up sure that Tuesday has gone missing. With help from a hedgehog, an owl, and a very patient snail, he learns that a good day is something you make rather than something you find.', 18.5, 'children', '["/images/fox-found-tuesday-1.png","/images/fox-found-tuesday-2.png","/images/fox-found-tuesday-3.png"]', '/images/fox-found-tuesday-1.png', '9781555550523', 2025, 1),
  (47, 'beyond-copper-ridge', 'Beyond the Copper Ridge', 'Asher Pike', 'A surveyor and a reluctant guide cross an unmapped mountain range in search of a lost observatory. The trail tests their loyalties as much as their endurance, and the ridge hides more than either expected.', 24.99, 'fiction', '["/images/beyond-copper-ridge-1.png","/images/beyond-copper-ridge-2.png","/images/beyond-copper-ridge-3.png"]', '/images/beyond-copper-ridge-1.png', '9781555550530', 2026, 1),
  (48, 'house-that-hums', 'The House That Hums', 'Vera Thorne', 'The empty house at the end of the lane hums a different melody every night. A sound archivist moves in to record it and discovers that the walls are remembering visitors who never left.', 23.5, 'mystery', '["/images/house-that-hums-1.png","/images/house-that-hums-2.png","/images/house-that-hums-3.png"]', '/images/house-that-hums-1.png', '9781555550547', 2025, 1),
  (49, 'miles-before-breakfast', 'Miles Before Breakfast', 'Tessa Cole', 'A joyful guide to building a running routine that fits real life. Training ideas, reflective essays, and approachable plans focus on consistency, curiosity, and enjoying the miles instead of chasing someone else''s pace.', 21.5, 'travel', '["/images/miles-before-breakfast-1.png","/images/miles-before-breakfast-2.png","/images/miles-before-breakfast-3.png"]', '/images/miles-before-breakfast-1.png', '9781555550554', 2026, 1),
  (50, 'little-machines-big-ideas', 'Little Machines, Big Ideas', 'Bea Lin', 'Discover how everyday mechanisms turn simple motion into useful work. Friendly diagrams, small build projects, and stories of invention introduce gears, levers, circuits, and the delight of asking how something works.', 28.0, 'nonfiction', '["/images/little-machines-big-ideas-1.png","/images/little-machines-big-ideas-2.png","/images/little-machines-big-ideas-3.png"]', '/images/little-machines-big-ideas-1.png', '9781555550561', 2025, 1);

